<?php

namespace App\Services;

use Carbon\CarbonImmutable;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\File;
use Illuminate\Support\Str;

class ChangelogService
{
    /**
     * Generated by GitHub for every release and only relevant to contributors
     * (dependency bumps, PR links), not to readers of the product changelog.
     */
    private const array HIDDEN_SECTIONS = ["What's Changed", 'New Contributors'];

    /**
     * @return list<array{version: string, date: string, anchor: string, html: string}>
     */
    public function releases(): array
    {
        $path = base_path('CHANGELOG.md');

        if (! File::exists($path)) {
            return [];
        }

        return Cache::remember(
            'changelog:'.File::lastModified($path),
            now()->addDay(),
            fn (): array => $this->parse(File::get($path)),
        );
    }

    /**
     * @return list<array{version: string, date: string, anchor: string, html: string}>
     */
    public function parse(string $markdown): array
    {
        preg_match_all('/^## (.+?) - (\d{4}-\d{2}-\d{2})[ \t]*$(.*?)(?=^## |\z)/ms', $markdown, $matches, PREG_SET_ORDER);

        return collect($matches)
            ->map(fn (array $match): array => [
                'version' => $match[1],
                'date' => CarbonImmutable::parse($match[2])->format('F j, Y'),
                'anchor' => trim(preg_replace('/[^A-Za-z0-9.]+/', '-', $match[1]), '-'),
                'body' => $this->stripHiddenContent($match[3]),
            ])
            ->reject(fn (array $release): bool => $release['body'] === '')
            ->map(fn (array $release): array => [
                'version' => $release['version'],
                'date' => $release['date'],
                'anchor' => $release['anchor'],
                'html' => Str::markdown($release['body'], ['html_input' => 'strip', 'allow_unsafe_links' => false]),
            ])
            ->values()
            ->all();
    }

    private function stripHiddenContent(string $body): string
    {
        $body = preg_replace('/^\*\*Full Changelog\*\*.*$/m', '', $body);

        return trim(collect(preg_split('/^(?=### )/m', $body))
            ->reject(fn (string $section): bool => in_array(
                trim(Str::after(Str::before($section, "\n"), '### ')),
                self::HIDDEN_SECTIONS,
                true,
            ))
            ->implode(''));
    }
}
